from pathlib import Path
import re

APP=Path('CaddieOS/App.js')
s=APP.read_text()

if 'BUILD69_FIELD_TEST' not in s:
    s=s.replace('const BUILD67_RESPONSIVE=true;', 'const BUILD67_RESPONSIVE=true;\nconst BUILD69_FIELD_TEST=true;', 1)

# Voice recognition must tolerate common speech-to-text variants such as "light Roth".
s=s.replace("for(const l of [...LIES].reverse())if(s.includes(l.toLowerCase())){S.setLie(l);break}", "if(/light\\s+(rough|ruff|roth|roof)/.test(s))S.setLie('Light Rough');else if(/deep\\s+(rough|ruff|roth|roof)/.test(s))S.setLie('Deep Rough');else if(/green(side)?\\s+bunker/.test(s))S.setLie('Greenside Bunker');else if(/fairway\\s+bunker/.test(s))S.setLie('Fairway Bunker');else if(/(rough|ruff|roth|roof)/.test(s))S.setLie('Rough');else for(const l of [...LIES].reverse())if(s.includes(l.toLowerCase())){S.setLie(l);break}", 1)

# Keep the header inside narrow phones and make the anti-glare state unmistakable.
s=re.sub(r"function Header\(\{go,antiGlare,setAntiGlare\}\)\{.*?\}\nfunction BottomNav", '''function Header({go,antiGlare,setAntiGlare}){return <View style={[s.header,antiGlare&&s.headerAnti]}><TouchableOpacity onPress={go} style={s.headerBrand}><Text style={s.brand} numberOfLines={1}>CADDIE<Text style={s.brandGold}>OS</Text></Text><Text style={s.brandSub} numberOfLines={1}>TOUR-LEVEL DECISIONS · YOUR GAME</Text></TouchableOpacity><TouchableOpacity onPress={()=>setAntiGlare(v=>!v)} style={[s.antiBtn,antiGlare&&s.antiBtnOn]}><Text style={s.anti} numberOfLines={1}>{antiGlare?'ANTI-GLARE ON':'ANTI-GLARE OFF'}</Text></TouchableOpacity></View>}
function BottomNav''',s,count=1,flags=re.S)

# Round recommendations must use a valid mapped centre distance, never stale Caddie input.
s=s.replace('gpsLive={gpsLive} startLiveGPS={startLiveGPS} stopLiveGPS={stopLiveGPS} targetDistances={targetDistances} wind={wind} windDir={windDir}', 'gpsLive={gpsLive} startLiveGPS={startLiveGPS} stopLiveGPS={stopLiveGPS} targetDistances={targetDistances} wind={wind} windDir={windDir} bag={bag}', 1)
s=s.replace("{page==='SCORE'&&<Score", "{page==='HOLESCORE'&&<HoleScore hole={hole} scores={scores} setScores={setScores} putts={putts} setPutts={setPutts} gir={gir} setGir={setGir} fw={fw} setFw={setFw} pen={pen} setPen={setPen} roundLog={roundLog} setRoundLog={setRoundLog} open={open}/>}\n {page==='SCORE'&&<Score", 1)

round_new='''function Round({hole,setHole,units,gps,gpsLive,startLiveGPS,stopLiveGPS,targetDistances,wind,windDir,bag,open}){const holes=Array.from({length:18},(_,i)=>String(i+1)),arrow=windDir==='HEAD'?'↓':windDir==='TAIL'?'↑':windDir==='L→R'?'→':'←',windType=windDir==='HEAD'?'HEADWIND':windDir==='TAIL'?'TAILWIND':'CROSSWIND',valid=targetDistances.center!==null&&targetDistances.center!==undefined,playing=valid?playsLike(targetDistances.center,wind,0,'Fairway',windDir,units):null,club=valid?nearestClub(playing,bag,units)[0]:'—';return <><Title kicker="ROUND" title={`Hole ${hole}`} sub={gpsLive?`LIVE GPS${gps?.acc?` · ±${gps.acc} m`:''}`:'GPS ready when you are'}/><View style={s.holeGrid}>{holes.map(x=><TouchableOpacity key={x} onPress={()=>setHole(x)} style={[s.holeGridButton,String(hole)===x&&s.holeGridOn]}><Text style={[s.holeGridText,String(hole)===x&&s.holeGridTextOn]}>{x}</Text></TouchableOpacity>)}</View><View style={[s.panel,{padding:10}]}><View style={s.mapTop}><Text style={s.panelTitle}>LIVE HOLE MAP</Text><Text style={[s.gpsStatus,gpsLive&&s.gpsStatusOn]}>{gpsLive?'● GPS ACTIVE':'GPS OFF'}</Text></View><View style={s.holeMap}><View style={s.mapGreen}/><View style={s.mapLine}/><View style={s.mapYou}/><Text style={s.mapFlag}>⚑</Text><Text style={s.mapYouText}>YOU</Text><View style={s.mapWind}><Text style={s.mapWindArrow}>{arrow}</Text><Text style={s.mapWindSpeed}>{wind||0} {units==='METRES'?'km/h':'mph'}</Text><Text style={s.mapWindType}>{windType}</Text></View></View></View><View style={s.windCompact}><View><Text style={s.panelTitle}>LIVE WIND</Text><Text style={s.windCompactLabel}>{windType}</Text></View><Text style={s.windCompactArrow}>{arrow}</Text><View style={{alignItems:'flex-end'}}><Text style={s.windCompactSpeed}>{wind||0}</Text><Text style={s.windCompactUnit}>{units==='METRES'?'km/h':'mph'}</Text></View></View><View style={s.panel}><Text style={s.panelTitle}>GREEN DISTANCES</Text><View style={s.distanceRow}><Stat a={targetDistances.front??'—'} b="FRONT"/><Stat a={targetDistances.center??'—'} b="CENTRE"/><Stat a={targetDistances.back??'—'} b="BACK"/></View><Text style={s.small}>{units==='METRES'?'metres':'yards'} · {gps?'GPS ACTIVE':'No position yet'}</Text></View><View style={s.panel}><Text style={s.panelTitle}>CADDIE RECOMMENDATION</Text><Text style={s.bigClub}>{club}</Text><Text style={s.cardSub}>{valid?`Playing ${playing} ${units==='METRES'?'m':'yd'} · ${windType} ${wind||0}`:'Map this green to calculate a live recommendation.'}</Text></View><Btn text={gpsLive?'STOP LIVE GPS':'START LIVE GPS'} onPress={gpsLive?stopLiveGPS:startLiveGPS}/><Btn text="OPEN CADDIE" onPress={()=>open('CADDIE')} outline/><Btn text="SCORE THIS HOLE" onPress={()=>open('HOLESCORE')} outline/></>}'''
s,n=re.subn(r"function Round\(.*?\nfunction Caddie",round_new+'\nfunction Caddie',s,count=1,flags=re.S)
if n!=1: raise SystemExit('Build 69: Round replacement failed')

# Fourteen editable slots; no preset club library and no remove buttons.
bag_new='''function Bag({bag,setBag,units}){const fixed=Array.from({length:14},(_,i)=>bag[i]||[`Club ${i+1}`,0]),rename=(i,v)=>setBag(fixed.map((x,k)=>k===i?[v,x[1]]:x)),change=(i,d)=>setBag(fixed.map((x,k)=>k===i?[x[0],Math.max(0,x[1]+d)]:x)),exact=(i,v)=>setBag(fixed.map((x,k)=>k===i?[x[0],Math.max(0,units==='METRES'?n(v):n(v)/1.09361)]:x));return <><Title kicker="MY BAG" title="14-Club Setup" sub="Enter your own clubs and carry distances"/>{fixed.map((x,i)=><View style={s.bagRow} key={i}><TextInput style={s.bagNameInput} value={x[0]} onChangeText={v=>rename(i,v)} placeholder={`Club ${i+1}`} placeholderTextColor={C.muted}/><TextInput style={s.bagInput} value={String(yd(x[1],units))} onChangeText={v=>exact(i,v)} keyboardType="numeric"/><Text style={s.unitMini}>{units==='METRES'?'m':'yd'}</Text><TouchableOpacity style={s.step} onPress={()=>change(i,-1)}><Text style={s.stepText}>−</Text></TouchableOpacity><TouchableOpacity style={s.step} onPress={()=>change(i,1)}><Text style={s.stepText}>+</Text></TouchableOpacity></View>)}</>}'''
s,n=re.subn(r"function Bag\(.*?\nfunction Course",bag_new+'\nfunction Course',s,count=1,flags=re.S)
if n!=1: raise SystemExit('Build 69: Bag replacement failed')

# A dedicated, thumb-friendly single-hole scoring surface.
hole_score='''function HoleScore({hole,scores,setScores,putts,setPutts,gir,setGir,fw,setFw,pen,setPen,roundLog,setRoundLog,open}){const i=Math.max(0,Math.min(17,n(hole)-1)),setA=(setter,a,v)=>setter(a.map((x,k)=>k===i?v:x)),step=(setter,a,d)=>setA(setter,a,String(Math.max(0,n(a[i])+d)));return <><Title kicker="SCORE THIS HOLE" title={`Hole ${hole}`} sub={`Par ${PARS[i]}`}/><View style={s.holeScoreCard}><Text style={s.holeScoreLabel}>STROKES</Text><View style={s.scoreStepper}><TouchableOpacity style={s.scoreStep} onPress={()=>step(setScores,scores,-1)}><Text style={s.scoreStepText}>−</Text></TouchableOpacity><Text style={s.scoreValue}>{scores[i]||0}</Text><TouchableOpacity style={s.scoreStep} onPress={()=>step(setScores,scores,1)}><Text style={s.scoreStepText}>+</Text></TouchableOpacity></View><Text style={s.holeScoreLabel}>PUTTS</Text><View style={s.scoreStepper}><TouchableOpacity style={s.scoreStep} onPress={()=>step(setPutts,putts,-1)}><Text style={s.scoreStepText}>−</Text></TouchableOpacity><Text style={s.scoreValue}>{putts[i]||0}</Text><TouchableOpacity style={s.scoreStep} onPress={()=>step(setPutts,putts,1)}><Text style={s.scoreStepText}>+</Text></TouchableOpacity></View><View style={s.scoreFlags}><TouchableOpacity style={[s.scoreFlag,gir[i]&&s.toggleOn]} onPress={()=>setA(setGir,gir,!gir[i])}><Text style={s.cardTitle}>GIR</Text></TouchableOpacity><TouchableOpacity style={[s.scoreFlag,fw[i]&&s.toggleOn]} onPress={()=>setA(setFw,fw,!fw[i])}><Text style={s.cardTitle}>FAIRWAY</Text></TouchableOpacity><TouchableOpacity style={[s.scoreFlag,n(pen[i])>0&&s.penaltyOn]} onPress={()=>setA(setPen,pen,n(pen[i])>0?'':'1')}><Text style={s.cardTitle}>PENALTY</Text></TouchableOpacity></View><Field label="RESULT / NOTE" value={roundLog[i]?.result||''} onChangeText={v=>setRoundLog(roundLog.map((x,k)=>k===i?{...x,result:v}:x))}/></View><Btn text="SAVE HOLE" onPress={()=>open('SCORE')}/></>}'''
s=s.replace('function Score({scores,',hole_score+'\nfunction Score({scores,',1)

# Nine-hole tables fit the portrait width without hidden holes.
s=s.replace('<ScrollView horizontal showsHorizontalScrollIndicator={false}><View>','<View>',2).replace('</View></ScrollView></View>;return','</View></View>;return',1)

# Warm-up is advice-only and condensed into three scan-friendly phase cards.
warm_new='''function WarmUp(){const phase=(title,time,items)=><View style={s.warmPhase}><View style={s.warmHead}><Text style={s.panelTitle}>{title}</Text><Text style={s.warmTime}>{time}</Text></View>{items.map((x,i)=><Text key={i} style={s.warmLine}>• <Text style={s.warmStrong}>{x[0]}:</Text> {x[1]}</Text>)}</View>;return <><Title kicker="PRE-ROUND" title="10-Minute Warm-Up" sub="Advice only · move smoothly and stay within your limits"/>{phase('WAKE UP THE BODY','3 MIN',WARM.slice(0,3))}{phase('BUILD THE FEEL','4 MIN',WARM.slice(3,6))}{phase('FIND THE SHOT','3 MIN',WARM.slice(6))}</>}'''
s,n=re.subn(r"function WarmUp\(.*?\nconst Check",warm_new+'\nconst Check',s,count=1,flags=re.S)
if n!=1: raise SystemExit('Build 69: WarmUp replacement failed')

# Richer hole-by-hole summary.
summary_new='''function Summary({scores,putts,total,totalPutts,toPar,totalPen,roundLog,open}){return <><Title kicker="ROUND" title="Round Summary" sub={`${total} strokes · ${toPar>=0?'+':''}${toPar} · ${totalPutts} putts · ${totalPen} penalties`}/>{scores.map((x,i)=>x?<View style={s.summaryRow} key={i}><Text style={s.holeNo}>{i+1}</Text><View style={s.flex}><Text style={s.cardTitle}>Score {x} · Putts {putts[i]||0}</Text><Text style={s.summaryLine}>SITUATION · {roundLog[i]?.situation||'Not recorded'}</Text><Text style={s.summaryLine}>ADVICE · {roundLog[i]?.advice||'Not recorded'}</Text><Text style={s.summaryLine}>CLUB · {roundLog[i]?.club||'Not recorded'}</Text><Text style={s.summaryLine}>RESULT · {roundLog[i]?.result||'Not recorded'}</Text></View></View>:null)}<Btn text="POST-ROUND CADDIE" onPress={()=>open('POSTROUND')}/></>}'''
s,n=re.subn(r"function Summary\(.*?\nfunction PostRound",summary_new+'\nfunction PostRound',s,count=1,flags=re.S)
if n!=1: raise SystemExit('Build 69: Summary replacement failed')

# Correct singular/plural wording.
s=s.replace('You completed ${played} holes.', "You completed ${played} ${played===1?'hole':'holes'}.",1)

# Course overview stays separate; all practical details share one compact card.
course_info='''function CourseInfo({course,info,setInfo}){const change=(k,v)=>setInfo({...info,[k]:v});return <><Title kicker="COURSE INFO" title={course||'Course Information'} sub="Keep the practical details in one place"/><View style={s.courseInfoCard}><Field label="PHONE" value={info.phone} onChangeText={v=>change('phone',v)}/><Field label="EMAIL" value={info.email} onChangeText={v=>change('email',v)}/><Field label="MEMBERSHIP" value={info.membership} onChangeText={v=>change('membership',v)}/><View style={s.courseInfoRow}><View style={s.flex}><Field label="CARTS" value={info.cart} onChangeText={v=>change('cart',v)}/></View><View style={s.flex}><Field label="CLUB HIRE" value={info.hire} onChangeText={v=>change('hire',v)}/></View></View><View style={s.courseInfoRow}><View style={s.flex}><Field label="PRO SHOP" value={info.proshop} onChangeText={v=>change('proshop',v)}/></View><View style={s.flex}><Field label="GOLF PRO" value={info.pro} onChangeText={v=>change('pro',v)}/></View></View></View><View style={s.panel}><Field label="COURSE OVERVIEW / NOTES" value={info.overview} onChangeText={v=>change('overview',v)}/></View></>}'''
s,n=re.subn(r"function CourseInfo\(.*?\n\nconst s=",course_info+'\n\nconst s=',s,count=1,flags=re.S)
if n!=1: raise SystemExit('Build 69: CourseInfo replacement failed')

# Append Build 69 style overrides. Last definitions win in React Native.
styles=",headerBrand:{flex:1,minWidth:0,paddingRight:7},antiBtn:{flexShrink:0,borderWidth:1.5,borderColor:C.blue,borderRadius:14,paddingHorizontal:8,paddingVertical:6,backgroundColor:'#F7F9FA'},antiBtnOn:{backgroundColor:'#B8C5CD',borderColor:C.navy},anti:{fontSize:8,color:C.navy,fontWeight:'900'},antiSafe:{backgroundColor:'#C9D0D5'},body:{paddingHorizontal:10,paddingTop:7,paddingBottom:28},bagNameInput:{flex:1,minWidth:92,height:34,borderWidth:1,borderColor:C.line,borderRadius:6,paddingHorizontal:7,paddingVertical:0,fontWeight:'900',color:C.navy,backgroundColor:C.white},bagInput:{width:54,height:34,borderWidth:1,borderColor:C.line,borderRadius:6,textAlign:'center',textAlignVertical:'center',paddingVertical:0,fontWeight:'900',fontSize:13,color:C.navy,backgroundColor:C.white},scoreLabel:{width:52,height:28,paddingHorizontal:3,textAlignVertical:'center',fontSize:8,fontWeight:'900',color:C.navy,borderWidth:.5,borderColor:C.line},scoreCellHead:{width:31,height:28,textAlign:'center',textAlignVertical:'center',fontSize:8,fontWeight:'900',color:C.navy,borderWidth:.5,borderColor:C.line},scoreCellPar:{width:31,height:27,textAlign:'center',textAlignVertical:'center',fontSize:8,color:C.muted,borderWidth:.5,borderColor:C.line},scoreCellInput:{width:31,height:30,textAlign:'center',textAlignVertical:'center',fontSize:9,fontWeight:'900',color:C.navy,backgroundColor:C.white,borderWidth:.5,borderColor:C.line,padding:0},routineRow:{flexDirection:'row',gap:5,alignItems:'center',marginBottom:3},numBox:{width:30,height:30,borderRadius:6,backgroundColor:C.panel2,alignItems:'center',justifyContent:'center'},repeat:{flexDirection:'row',alignItems:'center',gap:7,backgroundColor:'#C6DCEB',borderRadius:8,padding:7,marginTop:3,borderWidth:1,borderColor:C.blue},summaryLine:{fontSize:9,color:C.muted,lineHeight:13,marginTop:2},warmPhase:{backgroundColor:C.panel,borderRadius:9,borderWidth:1,borderColor:C.line,padding:9,marginBottom:7},warmHead:{flexDirection:'row',justifyContent:'space-between',alignItems:'center',marginBottom:3},warmTime:{fontSize:9,fontWeight:'900',color:C.blue},warmLine:{fontSize:10,color:C.text,lineHeight:15,marginTop:2},warmStrong:{fontWeight:'900',color:C.navy},courseInfoCard:{backgroundColor:C.panel,borderRadius:10,padding:10,marginBottom:7,borderWidth:1,borderColor:C.line},courseInfoRow:{flexDirection:'row',gap:7},holeGrid:{flexDirection:'row',flexWrap:'wrap',gap:5,marginBottom:9},holeGridButton:{width:'15.2%',minHeight:34,borderRadius:8,alignItems:'center',justifyContent:'center',backgroundColor:'#153348',borderWidth:1,borderColor:'#315064'},holeGridOn:{backgroundColor:C.blue,borderColor:C.blue},holeGridText:{fontSize:10,fontWeight:'900',color:C.white},holeGridTextOn:{color:C.white},mapTop:{flexDirection:'row',justifyContent:'space-between',alignItems:'center'},gpsStatus:{fontSize:9,fontWeight:'900',color:C.muted},gpsStatusOn:{color:C.blue},holeMap:{height:185,borderRadius:14,backgroundColor:'#173F35',borderWidth:2,borderColor:'#315D4E',overflow:'hidden',alignItems:'center'},mapGreen:{position:'absolute',top:14,width:82,height:42,borderRadius:41,backgroundColor:C.green,borderWidth:3,borderColor:C.white},mapLine:{position:'absolute',top:33,width:4,height:118,backgroundColor:'#B4C88A',opacity:.7},mapYou:{position:'absolute',bottom:18,width:18,height:18,borderRadius:9,backgroundColor:C.blue,borderWidth:3,borderColor:C.white},mapFlag:{position:'absolute',top:25,fontSize:16,fontWeight:'900',color:C.navy},mapYouText:{position:'absolute',bottom:4,fontSize:9,fontWeight:'900',color:C.white},mapWind:{position:'absolute',right:10,top:10,backgroundColor:'rgba(4,19,30,.82)',borderRadius:10,paddingHorizontal:9,paddingVertical:7,alignItems:'center'},mapWindArrow:{fontSize:27,fontWeight:'900',color:C.blue},mapWindSpeed:{fontSize:13,fontWeight:'900',color:C.white},mapWindType:{fontSize:9,fontWeight:'900',color:'#69BCE9'},windCompact:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',backgroundColor:C.panel,borderWidth:1,borderColor:C.line,borderRadius:10,padding:10,marginBottom:7},windCompactLabel:{fontSize:11,fontWeight:'900',color:C.muted},windCompactArrow:{width:58,height:58,borderRadius:29,textAlign:'center',textAlignVertical:'center',fontSize:32,fontWeight:'900',color:C.blue,backgroundColor:C.navy},windCompactSpeed:{fontSize:28,fontWeight:'900',color:C.navy},windCompactUnit:{fontSize:11,fontWeight:'900',color:C.muted},holeScoreCard:{backgroundColor:C.panel,borderRadius:10,padding:12,borderWidth:1,borderColor:C.line,marginBottom:8},holeScoreLabel:{fontSize:10,fontWeight:'900',letterSpacing:1,color:C.navy,textAlign:'center',marginTop:3},scoreStepper:{flexDirection:'row',alignItems:'center',justifyContent:'center',gap:20,marginVertical:7},scoreStep:{width:58,height:48,borderRadius:9,backgroundColor:C.navy,alignItems:'center',justifyContent:'center'},scoreStepText:{fontSize:30,fontWeight:'900',color:C.white},scoreValue:{minWidth:70,textAlign:'center',fontSize:42,fontWeight:'900',color:C.navy},scoreFlags:{flexDirection:'row',gap:6,marginVertical:10},scoreFlag:{flex:1,minHeight:46,borderRadius:8,backgroundColor:C.panel2,alignItems:'center',justifyContent:'center',borderWidth:1,borderColor:C.line},penaltyOn:{backgroundColor:'#F1D4D0'}"
idx=s.rfind('});')
if idx<0: raise SystemExit('Build 69: styles marker missing')
s=s[:idx]+styles+s[idx:]

APP.write_text(s)

g=Path('CaddieOS/android/app/build.gradle')
if g.exists():
    t=g.read_text()
    t=re.sub(r'versionCode\s+\d+','versionCode 69',t,count=1)
    t=re.sub(r'versionName\s+"[^"]+"','versionName "1.0.69"',t,count=1)
    g.write_text(t)

print('Build 69 field-test fixes applied')
